<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigWebauthnEnabledAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWebauthnEnabledAccessor trait.
 *
 * Covers null default, string/VO assignment via withWebauthnEnabled,
 * getWebauthnEnabled/webauthnEnabled accessors, and isWebauthnEnabledChanged with/without original.
 */
class TenantConfigWebauthnEnabledAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWebauthnEnabled creates a new instance with the WebauthnEnabled set
     * from a string value, and getWebauthnEnabled returns the primitive string.
     */
    public function testWithWebauthnEnabledFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnEnabledAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isWebauthnEnabled());
    }
    /**
     * Asserts that withwebauthnEnabled has access to the value object
     * from a string value, and getWebauthnEnabled returns the primitive string.
     */
    public function testWithWebauthnEnabledFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnEnabledAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnEnabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->webauthnEnabled()->value());
    }
    public function testChangedWebauthnEnabled(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnEnabledAccessorUnitTest();
        $original = $holder->withWebauthnEnabled(true);
        $same = $holder->withWebauthnEnabled(true);
        $modified = $holder->withWebauthnEnabled(false);

        // Act
        $unchanged = $holder->isWebauthnEnabledChanged();
        $withSame = $original->isWebauthnEnabledChanged($same);
        $withDiferent = $original->isWebauthnEnabledChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigWebauthnEnabledAccessorUnitTest
{
    use TenantConfigWebauthnEnabledAccessor;
}
